{
  "candidate_edge_types": [
    {
      "name": "FAILURE_PROMPTS_ALTERNATIVE_APPROACH",
      "definition": "A subsequent agent action responds to an earlier observed execution failure (such as an unavailable tool or command) by attempting a different method to accomplish the same sub-goal.",
      "source_description": "An earlier observed execution failure indicating that a required tool, command, or capability is unavailable or unsuccessful.",
      "target_description": "A subsequent agent action that uses an alternative method or tool to pursue the same sub-goal that the failed attempt could not achieve."
    },
    {
      "name": "SUCCESSFUL_PROBE_ENABLES_BROADER_APPLICATION",
      "definition": "A subsequent agent action generalizes or scales up a method that was first confirmed to work in an earlier, smaller-scale probe.",
      "source_description": "An earlier execution result confirming that a method or capability works on a single test input.",
      "target_description": "A subsequent agent action that applies the same confirmed method across multiple inputs or at a larger scale."
    },
    {
      "name": "EXTRACTS_REQUIRED_DATA_FROM_RESOURCE",
      "definition": "An agent inspects a provided resource file and derives a specific piece of required data or component (such as a protein sequence) that is retained for later task execution.",
      "source_description": "An agent action that inspects or reads a provided resource file to obtain task-relevant content.",
      "target_description": "The specific required data or component extracted from that resource and retained for subsequent use in the task."
    },
    {
      "name": "PRIOR_RESULT_USED_AS_INPUT",
      "definition": "Data obtained from an earlier tool observation or resource listing is consumed as input, argument, or iteration set by a subsequent agent action.",
      "source_description": "An earlier tool observation or resource listing that produced usable data or an enumeration of items.",
      "target_description": "A subsequent agent action that consumes that previously obtained data as input, argument, or the set of items to operate on."
    }
  ]
}

